const incoming = $json.body ?? $json;
const requestId = incoming.request_id || incoming.id || `req_${Date.now()}`;
const command = incoming.command || incoming.text || incoming.prompt || incoming.query || 'crear documento excel';
const serviceUrl = incoming.service_url || incoming.agent_url || incoming.command_agent_url || 'http://127.0.0.1:53320/agent/execute';
const apiKey = incoming.agent_api_key || incoming.command_agent_api_key || '';

return [{
  json: {
    request_id: requestId,
    service_url: serviceUrl,
    agent_api_key: apiKey,
    workflow_stage: 'normalized_for_transcriptor2_command_agent',
    agent_request: {
      request_id: requestId,
      command,
      use_latest_voice: Boolean(incoming.use_latest_voice || incoming.latest || incoming.use_latest_audio),
      use_gemma: incoming.use_gemma === undefined ? true : Boolean(incoming.use_gemma),
      context: {
        router: incoming.router || {},
        source: incoming.source || 'n8n_webhook',
        voice_input_dir: incoming.voice_input_dir || 'D:\\118102025\\Downloads\\Nueva carpeta\\Transcriptor2\\mp3',
        requested_by: incoming.requested_by || 'local_user'
      }
    }
  }
}];

const res = $json;
const ok = res.ok === undefined ? !Boolean(res.error) : Boolean(res.ok);
return [{
  json: {
    ok,
    workflow: 'transcriptor2-voice-office-gemma-command-agent',
    policy: 'n8n_orquesta; Function Gemma local decide tool; agente ejecuta solo whitelist Office/DiscoC',
    request_id: res.request_id || null,
    command: res.command || null,
    tool_call: res.tool_call || null,
    result: res.result || null,
    action_plan_path: res.action_plan_path || null,
    latest_voice: res.latest_voice || null,
    error: res.error || null,
    troubleshooting: ok ? null : 'Verifica que CommandAgentAPI este activo y que service_url apunte a la PC correcta o al tunnel Cloudflare.',
    timestamp: res.timestamp || new Date().toISOString()
  }
}];
